"""Derive separate per-arm ABAB metrics from unchanged independently audited inputs; never pool percentiles."""
import argparse,hashlib,json,pathlib
p=argparse.ArgumentParser();g=p.add_mutually_exclusive_group(required=True);g.add_argument('--runtime',type=pathlib.Path);g.add_argument('--evidence-root',type=pathlib.Path);p.add_argument('--output',type=pathlib.Path,required=True);a=p.parse_args();pins={};arms=[]
def read(path):
 raw=path.read_bytes();pins[str(path)]={'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest()};return json.loads(raw)
release=read(a.runtime/'window-root-freeze-r1/release.json' if a.runtime else a.evidence_root/'round-1/collection-run/collection/raw-files/source/release/release.json')
for n in (1,2):
 root=a.runtime/('window-cloud-collection-round-%d-r1'%n) if a.runtime else a.evidence_root/('round-%d'%n)/'collection-run'
 raw=read(root/'strict-raw-audit/result.json');native=read(root/'strict-native-audit/result.json');final=read(root/'finalized/LOCAL_COLLECTION_COMPLETE.json');review=read((a.runtime/('window-root-round-1-review-r2' if n==1 else 'window-root-round-2-review-r1') if a.runtime else a.evidence_root/('round-%d'%n)/('root-review-passed-r2' if n==1 else 'root-review-passed-r1'))/'ROOT_REVIEW.json')
 assert all(x['passed'] and x['round']==n for x in (raw,native,final,review))
 assert raw['sourceCommit']==native['sourceCommit']==release['sourceCommit']=='0f7eb2e7f6409a81b9a816fdb3142941d1850013'
 assert native['frozenCodeFingerprintIndependentlyRecomputed']==release['codeFingerprint']=='b148bbd416beca0c63ec10a2921a7709f1e82e8f3263604c930d5d901367117b'
 for arm,check in zip(raw['arms'],review['arms']):
  m=arm['rawMetrics'];c=arm['config'];w=arm['readWindow'];assert w==check['readWindow'] and m['allArrivalP99Ns']==check['allArrivalP99Ns']
  assert c['ratePerSecond']==500 and c['arrivals']==6400 and c['windowSeconds']==12.8 and c['batchCap']==4 and c['archiveChunkBytes']==6144 and c['eventFetchCount']==16 and c['readWindow']==w
  assert c['profileSha256']==release['profileFingerprint'] and c['actualCodeSha256']==release['codeFingerprint']
  assert all(m[k]==0 for k in ['notSent','unknownFinal','unknownObserved','serverRejected','schedulerLatenessOver20ms']) and m['confirmedAcceptedUniqueOrders']==6400
  assert sum(x['durationNs'] for x in arm['cycles'])==arm['totalMaintenanceCycleNs']==check['maintenanceCycleWallNs'] and len(arm['cycles'])==3
  assert arm['readPhaseBindings']['actualOfferedHighWater']==w
  arms.append({'label':('A' if w==1 else 'B')+str(n),'round':n,'readWindow':w,'plannedArrivals':6400,'acceptedUnique':6400,'allArrivalP99Ns':m['allArrivalP99Ns'],'arrivalLatencyP50Ns':arm['arrivalLatencyP50Ns'],'arrivalWindowGoodputPerSecond':m['arrivalWindowGoodputPerSecond'],'acceptedInside12Point8Seconds':m['acceptedOrdersInArrivalWindow'],'lastReplyDrainNs':m['lastKnownReplyDrainNs'],'maintenanceCycleWallNs':arm['totalMaintenanceCycleNs'],'cycleDurationsNs':[x['durationNs'] for x in arm['cycles']],'logicalMaintenanceRpcs':arm['logicalMaintenanceRpcs'],'physicalRequests':arm['physicalRequests'],'businessBatchFrameCounts':arm['batchSizePhysicalFrameCounts'],'offeredAwaitingFirstCallbackHighWater':arm['readPhaseBindings']['actualOfferedHighWater'],'notSent':0,'rejected':0,'unknown':0,'invalidSchedulerArrivals':0})
pairs=[]
for left,right in [(arms[0],arms[1]),(arms[2],arms[3])]:
 pairs.append({'round':left['round'],'allArrivalP99ReductionPercent':100*(1-right['allArrivalP99Ns']/left['allArrivalP99Ns']),'maintenanceCycleWallReductionPercent':100*(1-right['maintenanceCycleWallNs']/left['maintenanceCycleWallNs']),'arrivalWindowGoodputDifferencePerSecond':right['arrivalWindowGoodputPerSecond']-left['arrivalWindowGoodputPerSecond']})
assert all(pathlib.Path(n).stat().st_size==r['bytes'] and hashlib.sha256(pathlib.Path(n).read_bytes()).hexdigest()==r['sha256'] for n,r in pins.items())
report={'passed':True,'schemaVersion':1,'sourceCommit':release['sourceCommit'],'codeFingerprint':release['codeFingerprint'],'profileFingerprint':release['profileFingerprint'],'sequence':['A1','B1','A2','B2'],'workload':'Each fresh lineage schedules6400 orders at500/s for12.8s, cap4/chunk6144/fetch16/read-window1or8; appointedleader0,Archive/catalog/consensus sync2,MTU1248.','hardware':'One existing shared CPU host, three JVMs over loopback UDP. Not independent hosts.','arms':arms,'pairedChanges':pairs,'percentilesPooled':False,'stableThroughputOr100MProven':False,'limitations':['Fixed-order ABAB, two repeats; no randomization, causal confidence interval or host exclusivity.','Each lineage has only two full3072-command maintenance cuts and one trailing partial cut. Short-window goodput and end-of-window outstanding replies do not establish sustained500/s capacity or an instability threshold.','All four lineages are distinct;25600 confirmed orders cannot be treated as one cumulative lineage.','Maintenance RPC elapsed intervals overlap; only complete cycle wall intervals are compared.','Archive payload forces/readback are included, but independent storage durability after Pod stop is not established.','Read bank retained-credit occupancy is source/runtime-attested; raw offered-to-first-callback overlap is independently reconstructed.'],'inputs':pins,'derivationSourceSha256':hashlib.sha256(pathlib.Path(__file__).read_bytes()).hexdigest()}
with a.output.open('x') as f:json.dump(report,f,indent=2,sort_keys=True);f.write('\n')
print(json.dumps({'passed':True,'pairedChanges':pairs,'outputSha256':hashlib.sha256(a.output.read_bytes()).hexdigest()},indent=2))
